<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Models\{Feedback,GalleryItem,Package,PageVisit,Service};
use Illuminate\Http\Request;
class PublicContentController extends Controller { public function services() { return Service::where('is_published',true)->latest()->get(); } public function packages() { return Package::where('is_published',true)->latest()->get(); } public function gallery() { return GalleryItem::where('is_published',true)->latest()->get(); } public function feedback(Request $r) { $data=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|max:150','phone'=>'nullable|string|max:40','package_id'=>'nullable|string|max:100','message'=>'required|string|max:3000']); return response()->json(Feedback::create([...$data,'type'=>'inquiry']),201); } public function testimonials() { return Feedback::where('type','testimonial')->where('is_published',true)->latest()->get()->map(fn($item)=>['id'=>(string)$item->id,'name'=>$item->name,'role'=>$item->role,'rating'=>$item->rating,'text'=>$item->message,'result'=>$item->result,'image'=>$item->image,'createdAt'=>$item->created_at]); } public function storeTestimonial(Request $r) { $data=$r->validate(['name'=>'required|string|max:100','role'=>'nullable|string|max:100','rating'=>'required|integer|min:1|max:5','text'=>'required|string|max:2000','result'=>'required|string|max:200']); return response()->json(Feedback::create(['type'=>'testimonial','name'=>$data['name'],'email'=>str()->slug($data['name']).'-'.str()->random(6).'@feedback.local','role'=>$data['role'],'rating'=>$data['rating'],'message'=>$data['text'],'result'=>$data['result'],'status'=>'new','is_published'=>false]),201); } public function visit(Request $r) { $data=$r->validate(['path'=>'required|string|max:255','visitor_id'=>'nullable|string|max:100']); PageVisit::create(['path'=>$data['path'],'visitor_hash'=>isset($data['visitor_id']) ? hash('sha256',$data['visitor_id']) : null,'referrer'=>substr((string) $r->header('Referer'),0,500) ?: null]); return response()->noContent(); } }
